export async function mount(root, { files }) {
  const faces = [];
  const specs = [['Noto Sans SC', '700'], ['Outfit', '600'], ['Outfit', '700'], ['Outfit', '800']];
  try {
    for (let i = 0; i < specs.length; i++) {
      const response = await files.get(`template-assets/fonts/font-${i + 1}.woff2`);
      if (!response.ok) throw new Error(`字体读取失败 (${response.status})`);
      const face = new FontFace(specs[i][0], await response.arrayBuffer(), { weight: specs[i][1], style: 'normal', display: 'swap' });
      await face.load();
      document.fonts.add(face);
      faces.push(face);
    }
  } catch (error) {
    faces.forEach(face => document.fonts.delete(face));
    root.textContent = '字体加载失败，请刷新后重试。';
    console.error('Font loading failed', error);
    return;
  }
document.head.insertAdjacentHTML("beforeend", "<style>\n:root {\n  --accent: #22d3ee;\n  --accent2: #8b5cf6;\n  --blue: #3b82f6;\n  --grad: linear-gradient(135deg, #22d3ee, #3b82f6 48%, #8b5cf6);\n  --bg: #06070a;\n  --bg-deep: #04050a;\n  --panel: rgba(255,255,255,0.03);\n  --panel-hover: rgba(255,255,255,0.055);\n  --border: rgba(255,255,255,0.08);\n  --border-strong: rgba(255,255,255,0.16);\n  --text: rgba(255,255,255,0.88);\n  --text-secondary: rgba(255,255,255,0.55);\n  --text-tertiary: rgba(255,255,255,0.35);\n  --radius: 12px;\n  --radius-lg: 18px;\n  --ease: cubic-bezier(0.16, 1, 0.3, 1);\n}\n* { box-sizing: border-box; }\nhtml { scroll-behavior: smooth; }\nbody {\n  margin: 0;\n  background: var(--bg);\n  color: var(--text);\n  font-family: \"Noto Sans SC\", -apple-system, \"PingFang SC\", \"Microsoft YaHei\", Segoe UI, sans-serif;\n  line-height: 1.75;\n  -webkit-font-smoothing: antialiased;\n  overflow-x: hidden;\n}\n.num, .mono { font-family: \"Outfit\", \"Noto Sans SC\", sans-serif; font-variant-numeric: tabular-nums; }\n\n/* ===== 背景氛围 ===== */\n.bg-ambient {\n  position: fixed; inset: 0; z-index: -2; pointer-events: none;\n  background:\n    radial-gradient(ellipse 70% 45% at 18% -8%, rgba(34,211,238,0.14), transparent 60%),\n    radial-gradient(ellipse 55% 45% at 82% 12%, rgba(139,92,246,0.10), transparent 62%),\n    radial-gradient(ellipse 60% 50% at 50% 110%, rgba(59,130,246,0.10), transparent 60%),\n    var(--bg);\n}\n.bg-grid {\n  position: fixed; inset: 0; z-index: -1; pointer-events: none; opacity: 0.5;\n  background-image:\n    linear-gradient(rgba(255,255,255,0.025) 1px, transparent 1px),\n    linear-gradient(90deg, rgba(255,255,255,0.025) 1px, transparent 1px);\n  background-size: 56px 56px;\n  -webkit-mask-image: radial-gradient(ellipse 80% 60% at 50% 0%, #000 30%, transparent 75%);\n  mask-image: radial-gradient(ellipse 80% 60% at 50% 0%, #000 30%, transparent 75%);\n}\n\n/* ===== 顶部进度条 ===== */\n.progress {\n  position: fixed; top: 0; left: 0; height: 2px; width: 100%; z-index: 50;\n  background: transparent;\n}\n.progress > i {\n  display: block; height: 100%; width: 0;\n  background: var(--grad);\n  box-shadow: 0 0 12px rgba(34,211,238,0.55);\n}\n\n.wrap { max-width: 1120px; margin: 0 auto; padding: 0 24px; }\n\n/* ===== Hero ===== */\n.hero {\n  position: relative;\n  min-height: 100vh;\n  display: flex; align-items: center;\n  padding: 96px 0 64px;\n}\n.hero-inner { max-width: 820px; }\n.hero-kicker {\n  display: inline-flex; align-items: center; gap: 10px;\n  font-size: 13px; letter-spacing: 0.14em; color: var(--accent);\n  text-transform: uppercase; margin-bottom: 24px;\n}\n.hero-kicker::before { content: \"\"; width: 34px; height: 1px; background: var(--grad); }\n.hero h1 {\n  margin: 0; font-family: \"Outfit\",\"Noto Sans SC\",sans-serif;\n  font-weight: 800; font-size: clamp(40px, 6.4vw, 76px);\n  line-height: 1.06; letter-spacing: -0.03em; color: #fff;\n}\n.hero h1 .g {\n  background: var(--grad);\n  -webkit-background-clip: text; background-clip: text; color: transparent;\n  -webkit-text-fill-color: transparent;\n}\n.hero-sub {\n  margin: 24px 0 0; max-width: 640px;\n  font-size: clamp(15px, 1.7vw, 19px); color: var(--text-secondary); line-height: 1.8;\n}\n.hero-meta {\n  display: flex; flex-wrap: wrap; gap: 12px; margin-top: 36px;\n}\n.chip {\n  display: inline-flex; align-items: center; gap: 8px;\n  padding: 8px 16px; border-radius: 999px;\n  border: 1px solid var(--border); background: var(--panel);\n  font-size: 13px; color: var(--text-secondary);\n  backdrop-filter: blur(8px); -webkit-backdrop-filter: blur(8px);\n}\n.chip b { color: var(--text); font-weight: 600; }\n.chip .dot { width: 6px; height: 6px; border-radius: 50%; background: var(--accent); box-shadow: 0 0 8px rgba(34,211,238,0.6); }\n.scroll-hint {\n  position: absolute; left: 0; bottom: 32px;\n  display: inline-flex; align-items: center; gap: 12px;\n  font-size: 12px; letter-spacing: 0.2em; color: var(--text-tertiary);\n}\n.scroll-hint::after {\n  content: \"\"; width: 1px; height: 40px;\n  background: linear-gradient(180deg, var(--accent), transparent);\n  animation: drip 2s var(--ease) infinite;\n}\n@keyframes drip {\n  0% { transform: scaleY(0); transform-origin: top; }\n  50% { transform: scaleY(1); transform-origin: top; }\n  51% { transform-origin: bottom; }\n  100% { transform: scaleY(0); transform-origin: bottom; }\n}\n\n/* ===== 数据条 ===== */\n.stats {\n  border-top: 1px solid var(--border);\n  border-bottom: 1px solid var(--border);\n  padding: 48px 0;\n}\n.stats-inner { display: flex; flex-wrap: wrap; }\n.stat {\n  flex: 1 1 200px; padding: 8px 32px; position: relative;\n}\n.stat + .stat::before {\n  content: \"\"; position: absolute; left: 0; top: 12%; bottom: 12%;\n  width: 1px; background: linear-gradient(180deg, transparent, var(--border-strong), transparent);\n}\n.stat .v {\n  font-family: \"Outfit\",sans-serif; font-weight: 800;\n  font-size: clamp(38px, 5vw, 60px); line-height: 1; letter-spacing: -0.02em;\n  background: var(--grad); -webkit-background-clip: text; background-clip: text; color: transparent;\n  -webkit-text-fill-color: transparent;\n}\n.stat .v .unit { font-size: 0.5em; font-weight: 700; }\n.stat .l { margin-top: 12px; font-size: 13px; color: var(--text-secondary); letter-spacing: 0.02em; }\n.stat .s { margin-top: 4px; font-size: 12px; color: var(--text-tertiary); }\n\n/* ===== 章节标题 ===== */\n.chapter-head {\n  padding: 96px 0 40px; position: relative;\n}\n.chapter-head .no {\n  font-family: \"Outfit\",sans-serif; font-weight: 800;\n  font-size: clamp(60px, 9vw, 120px); line-height: 0.9; letter-spacing: -0.04em;\n  color: transparent; -webkit-text-stroke: 1px rgba(255,255,255,0.14);\n  position: absolute; right: 0; top: 60px; user-select: none;\n}\n.chapter-head h2 {\n  margin: 0; font-family: \"Outfit\",\"Noto Sans SC\",sans-serif; font-weight: 700;\n  font-size: clamp(28px, 4vw, 44px); letter-spacing: -0.02em; color: #fff;\n  display: flex; align-items: center; gap: 16px; flex-wrap: wrap;\n}\n.chapter-head h2 .bar { width: 44px; height: 4px; border-radius: 2px; background: var(--grad); }\n.chapter-head .range {\n  margin-top: 12px; font-family: \"Outfit\",sans-serif; font-weight: 600;\n  font-size: 15px; letter-spacing: 0.12em; color: var(--accent);\n}\n\n/* ===== 时间轴 ===== */\n.timeline { position: relative; padding: 24px 0 32px; }\n.tl-line {\n  position: absolute; left: 50%; top: 0; bottom: 0; width: 2px;\n  margin-left: -1px; border-radius: 2px;\n  background: linear-gradient(180deg, transparent, rgba(34,211,238,0.7) 6%, rgba(59,130,246,0.7) 50%, rgba(139,92,246,0.7) 94%, transparent);\n}\n.tl-fill {\n  position: absolute; left: 50%; top: 0; width: 2px; margin-left: -1px; height: 0;\n  background: var(--grad); border-radius: 2px;\n  box-shadow: 0 0 16px rgba(34,211,238,0.5);\n}\n.milestone { position: relative; width: 50%; padding: 14px 48px 14px 0; }\n.milestone:nth-child(odd) { left: 0; text-align: right; padding: 14px 48px 14px 0; }\n.milestone:nth-child(even) { left: 50%; text-align: left; padding: 14px 0 14px 48px; }\n.tl-node {\n  position: absolute; top: 26px; width: 14px; height: 14px; border-radius: 50%;\n  background: var(--bg); border: 2px solid var(--accent);\n  box-shadow: 0 0 0 4px rgba(34,211,238,0.12), 0 0 18px rgba(34,211,238,0.35);\n  transition: box-shadow .5s var(--ease), border-color .5s var(--ease), background .5s var(--ease);\n}\n.milestone:nth-child(odd) .tl-node { right: -8px; }\n.milestone:nth-child(even) .tl-node { left: -8px; }\n.milestone.lit .tl-node {\n  background: var(--accent); border-color: var(--accent);\n  box-shadow: 0 0 0 5px rgba(34,211,238,0.16), 0 0 28px rgba(34,211,238,0.5);\n}\n.ms-card {\n  display: inline-block; width: 100%; max-width: 460px;\n  background: var(--panel); border: 1px solid var(--border);\n  border-radius: var(--radius-lg); padding: 22px 24px;\n  backdrop-filter: blur(10px); -webkit-backdrop-filter: blur(10px);\n  transition: transform .4s var(--ease), border-color .4s var(--ease), background .4s var(--ease);\n}\n.milestone:nth-child(odd) .ms-card { text-align: left; }\n.ms-card:hover {\n  transform: translateY(-3px);\n  border-color: var(--border-strong); background: var(--panel-hover);\n}\n.ms-year {\n  font-family: \"Outfit\",sans-serif; font-weight: 800;\n  font-size: 30px; line-height: 1; letter-spacing: -0.02em;\n  background: var(--grad); -webkit-background-clip: text; background-clip: text; color: transparent;\n  -webkit-text-fill-color: transparent;\n}\n.ms-tag {\n  display: inline-block; margin-top: 8px; padding: 3px 10px;\n  border-radius: 999px; border: 1px solid rgba(34,211,238,0.25);\n  color: var(--accent); font-size: 11px; letter-spacing: 0.06em;\n}\n.ms-title { margin: 12px 0 8px; font-size: 18px; font-weight: 700; color: #fff; line-height: 1.4; }\n.ms-desc { margin: 0; font-size: 14px; color: var(--text-secondary); line-height: 1.7; }\n.ms-fact {\n  margin-top: 14px; padding: 10px 14px; border-radius: 10px;\n  background: rgba(34,211,238,0.06); border: 1px solid rgba(34,211,238,0.12);\n  font-size: 12.5px; color: var(--text-secondary);\n}\n.ms-fact b { color: var(--accent); font-family: \"Outfit\",sans-serif; font-weight: 700; }\n\n/* ===== 算力曲线 ===== */\n.growth { padding: 88px 0 40px; }\n.growth h3 {\n  margin: 0 0 8px; font-family: \"Outfit\",\"Noto Sans SC\",sans-serif; font-weight: 700;\n  font-size: clamp(24px, 3.4vw, 36px); letter-spacing: -0.02em; color: #fff;\n}\n.growth .lead { margin: 0 0 40px; color: var(--text-secondary); font-size: 15px; max-width: 620px; }\n.chart-card {\n  background: var(--panel); border: 1px solid var(--border);\n  border-radius: var(--radius-lg); padding: 28px; overflow-x: auto;\n  backdrop-filter: blur(10px); -webkit-backdrop-filter: blur(10px);\n}\n.chart-card svg { display: block; width: 100%; min-width: 560px; height: auto; }\n.chart-label { font-family: \"Outfit\",sans-serif; fill: var(--text-tertiary); font-size: 11px; }\n.chart-axis { stroke: rgba(255,255,255,0.08); }\n.chart-line {\n  fill: none; stroke-width: 2.5; stroke-linecap: round;\n  stroke: url(#gline);\n  filter: drop-shadow(0 0 6px rgba(34,211,238,0.4));\n}\n.chart-area { fill: url(#garea); opacity: 0.9; }\n.chart-pt { fill: var(--accent); }\n.chart-pt-ring { fill: rgba(34,211,238,0.15); }\n\n/* ===== 结语 ===== */\n.outro { padding: 96px 0 120px; position: relative; }\n.quote {\n  border-left: 3px solid var(--accent);\n  background: var(--panel); border-radius: 0 var(--radius-lg) var(--radius-lg) 0;\n  padding: 40px 44px; max-width: 820px;\n}\n.quote p {\n  margin: 0; font-family: \"Outfit\",\"Noto Sans SC\",sans-serif; font-weight: 600;\n  font-size: clamp(20px, 2.6vw, 30px); line-height: 1.5; color: #fff;\n}\n.quote p .g {\n  background: var(--grad); -webkit-background-clip: text; background-clip: text; color: transparent;\n  -webkit-text-fill-color: transparent;\n}\n\n/* ===== 页脚 ===== */\nfooter {\n  border-top: 1px solid var(--border); padding: 40px 0 56px;\n  display: flex; justify-content: space-between; gap: 16px; flex-wrap: wrap;\n  color: var(--text-tertiary); font-size: 12px; letter-spacing: 0.02em;\n}\nfooter .sig { color: var(--text-secondary); }\n\n/* ===== 底部二进制彩带 ===== */\n.binary {\n  padding: 32px 0 44px;\n  border-top: 1px solid var(--border);\n}\n.binary-head {\n  display: flex; align-items: center; gap: 12px; flex-wrap: wrap;\n  font-family: \"Outfit\", monospace; font-size: 13px;\n  color: var(--text-tertiary); margin-bottom: 32px;\n}\n.binary-head .prompt { color: var(--accent); font-weight: 700; }\n.binary-head .msg { color: var(--text); letter-spacing: 0.06em; }\n.binary-head .hint { margin-left: auto; font-size: 12px; color: var(--text-tertiary); letter-spacing: 0.02em; }\n.b-stage { display: flex; flex-wrap: wrap; gap: 28px 40px; }\n.b-unit { display: flex; flex-direction: column; align-items: center; gap: 5px; }\n.b-byte {\n  display: flex; font-family: \"Outfit\", monospace;\n  font-size: 16px; line-height: 1.25; letter-spacing: 0.03em;\n}\n.b-bit { min-width: 0.62em; text-align: center; }\n.b1 { color: var(--accent); }\n.b0 { color: rgba(255,255,255,0.20); }\n.b-label { font-size: 13px; font-weight: 600; color: var(--text-secondary); margin-top: 2px; }\n\n/* ===== 滚动入场 ===== */\n.reveal { opacity: 0; transform: translateY(26px); transition: opacity .7s var(--ease), transform .7s var(--ease); }\n.reveal.in { opacity: 1; transform: none; }\n.reveal-blur { opacity: 0; filter: blur(8px); transition: opacity .8s var(--ease), filter .8s var(--ease); }\n.reveal-blur.in { opacity: 1; filter: none; }\n\n@media (prefers-reduced-motion: reduce) {\n  .reveal, .reveal-blur { opacity: 1; transform: none; filter: none; transition: none; }\n  .scroll-hint::after { animation: none; }\n}\n\n/* ===== 响应式 ===== */\n@media (max-width: 760px) {\n  .hero { padding: 72px 0 48px; }\n  .chapter-head .no { font-size: clamp(40px, 13vw, 72px); top: 84px; }\n  .stat { flex: 1 1 100%; padding: 16px 0; }\n  .stat + .stat::before { display: none; }\n  .stat + .stat { border-top: 1px solid var(--border); }\n  /* 移动端：主轴移到左侧，卡片统一右置 */\n  .tl-line, .tl-fill { left: 10px; }\n  .milestone, .milestone:nth-child(odd), .milestone:nth-child(even) {\n    width: 100%; left: 0; text-align: left; padding: 14px 0 14px 40px;\n  }\n  .milestone:nth-child(odd) .tl-node, .milestone:nth-child(even) .tl-node { left: 3px; right: auto; }\n  .ms-card { max-width: 100%; }\n  .quote { padding: 32px 24px; }\n}\n</style>");
root.innerHTML = "\n<div data-page-node-id=\"HNwS2SqfFkECZrp0yrXfZN\" class=\"bg-ambient\"></div>\n<div data-page-node-id=\"urTMBZmvJAZwiQts95E1PQ\" class=\"bg-grid\"></div>\n<div data-page-node-id=\"d4edaIoaHIGNRxJ3gC53G2\" class=\"progress\"><i data-page-node-id=\"vTzJkE9bsSGYylVVcDBRU4\" id=\"progressBar\"></i></div>\n\n<!--pnid:RO5yETRVPqOjcGldU8ToVe--><!-- ===== Hero ===== -->\n<header data-page-node-id=\"68twjE98pROWVFD8EAji8W\" class=\"hero\">\n  <div data-page-node-id=\"sgPexEpg34YcPcGBKOTIYE\" class=\"wrap\">\n    <div data-page-node-id=\"eFHPUoxyicDqEi83LJAxGl\" class=\"hero-inner\">\n      <div data-page-node-id=\"xlw2io37Kc5lpNdug6KJe3\" class=\"hero-kicker reveal\"><!--pnid:qNRdTwGZOklskXXAkVfyrl-->Computing · 算力进化史</div>\n      <h1 data-page-node-id=\"8WbJcdQbYHdGIYSbfMnv4U\" class=\"reveal-blur\"><!--pnid:NmUMo9xNPkoWLCyJnpg8lB-->从一颗晶体管<br data-page-node-id=\"Ok5S93p1TEShxs1J7tNUsT\"><!--pnid:gGirNaR7ayx3kDeGLinPIv-->到<span data-page-node-id=\"aVQIbzb7LeaL2BPVjsVd2p\" class=\"g\"><!--pnid:g6CzshLvllNCgLTbPdshJx-->大模型时代</span></h1>\n      <p data-page-node-id=\"jehf9FSLWJ4wV1MfAreVjN\" class=\"hero-sub reveal\"><!--pnid:vTVeKgriVFOwJiLWIQyu6w-->从机械齿轮的咬合，到千亿晶体管的大模型芯片；从每秒几次运算的电子管，到每秒百万亿亿次的智算集群。一部算力的跃迁史，就是一部人类智能的延伸史。</p>\n      <div data-page-node-id=\"tpINsOcbH2bTkQqo6p2xlL\" class=\"hero-meta reveal\">\n        <span data-page-node-id=\"8lJNf0sujR7wy3ECNWWfEY\" class=\"chip\"><span data-page-node-id=\"scKWHuxYZ2Og4gHdUIk14F\" class=\"dot\"></span><!--pnid:QFYJsTEIbJhKQHyUfw00hZ-->5 大时代</span>\n        <span data-page-node-id=\"WE0LHNhbPjfAUFbzXrVDjV\" class=\"chip\"><b data-page-node-id=\"ASpOrvPsywHHQTCgdHvQ1m\"><!--pnid:HUyusYFGGhnbfhRdSV1Kh5-->24</b><!--pnid:R35Apw7fJWXgvvYXwAhWIJ--> 个里程碑</span>\n        <span data-page-node-id=\"XLQwP9FvIUbXdnR78AZKVe\" class=\"chip\"><!--pnid:kOp6rkPXRpKlM531H54V5H-->1642 → <b data-page-node-id=\"1byil6VmWiDKpmrwuP3uI7\"><!--pnid:WGtU2E7zu7NDZ2HZZhfIiy-->2025</b></span>\n        <span data-page-node-id=\"dVSbi7QLb6iIC1LGzPjvxP\" class=\"chip\"><!--pnid:TigXqPFDh90iyIJzPdQMn2-->算力增长 <b data-page-node-id=\"ZQLhjtQHc4OlXEkK9fBkJf\"><!--pnid:BevUvbR4uMb3UuuIOpsVr1-->10⁹</b><!--pnid:eRrCe5HrvnSNya9jjYvqNw--> 倍</span>\n      </div>\n    </div>\n    <div data-page-node-id=\"jcQSmgEygwhWx54maWTteP\" class=\"scroll-hint\"><!--pnid:kTbvwKvA5Ye7YYMr5A19IF-->向下滚动 · 探索时间轴</div>\n  </div>\n</header>\n\n<!--pnid:Sc1lawohIul0QxtVRguIBn--><!-- ===== 数据里程碑 ===== -->\n<section data-page-node-id=\"3K7adyU08cBYcVyM4YCQDj\" class=\"stats\">\n  <div data-page-node-id=\"itk8E1rThHsdqew1HDMLBD\" class=\"wrap stats-inner\">\n    <div data-page-node-id=\"5lqvkgxJ56PGbZQwIWUXKb\" class=\"stat reveal\">\n      <div data-page-node-id=\"g7Ab33lFRbdOMvUqtIGDjU\" class=\"v\">约<span data-page-node-id=\"VVDRo0nZzURT1ZFzzNtz1g\" class=\"num\" data-count=\"3500\"><!--pnid:3RjKb8PCa7jt5qSrsJVU9T-->0</span><span data-page-node-id=\"450XnrleRswXve24I9VUkp\" class=\"unit\"><!--pnid:txQfcD2bbqKwWJZgiegrT8-->万倍</span></div>\n      <div data-page-node-id=\"osRpIOcHpsg7G2EzQCrb06\" class=\"l\"><!--pnid:2aqtqBKSR2UGqmve64cqmU-->单芯片晶体管数量增长</div>\n      <div data-page-node-id=\"2TY37yLCW9wvDMc2GkPvdU\" class=\"s\"><!--pnid:FaqYraum744YhAu1IBLobz-->Intel 4004 的 2300 颗 → H100 的 800 亿颗</div>\n    </div>\n    <div data-page-node-id=\"UIlXjRpRF7aOg0jA2Wvv8n\" class=\"stat reveal\">\n      <div data-page-node-id=\"ryshuKRxkhdk0PI9oWi33S\" class=\"v\"><span data-page-node-id=\"h2NGlU4Qv1e8J2xPCty9eu\" class=\"num\" data-count=\"1500\"><!--pnid:OmzWsYLtaTAXQ93UhgnmU6-->0</span><span data-page-node-id=\"goRwP4utK68gFkIsx9cUB6\" class=\"unit\"><!--pnid:71Njj9zdNIqvCxOWY4jegf-->倍</span></div>\n      <div data-page-node-id=\"pySKYxAqq9JO7YNJLxAu0R\" class=\"l\"><!--pnid:FgD7dLYTqkToaxSxTcb8Uf-->模型参数量增长</div>\n      <div data-page-node-id=\"BonvGB1vXV3VBQd3AZ9xSU\" class=\"s\"><!--pnid:nlAC50hpvlKGuVGVJKq6Go-->GPT-1 的 1.17 亿 → GPT-3 的 1750 亿</div>\n    </div>\n    <div data-page-node-id=\"0qoFReaWM6Ud6BVrA2xQvC\" class=\"stat reveal\">\n      <div data-page-node-id=\"l3OBEGUMRl7pUbrjznXDsk\" class=\"v\"><span data-page-node-id=\"61XIK6XxcoGI3Rogyx65Kq\" class=\"num\" data-count=\"100\"><!--pnid:6LI2Sng0W9kBLA2JD1vUlq-->0</span><span data-page-node-id=\"2tT3qNv8lkijgqXIJiRymc\" class=\"unit\"><!--pnid:OjsoRtbN8c3TpCeZ3mbTI2-->亿倍</span></div>\n      <div data-page-node-id=\"uMyO2KdM2uWK2wVl9R2sM2\" class=\"l\"><!--pnid:YF9LUmFSEUrjQdoZ46H6im-->前沿训练算力增长（十年间）</div>\n      <div data-page-node-id=\"fRwYGkfRvchBYgKDIv9SL0\" class=\"s\"><!--pnid:ryLv5GbMSS2bLSGJCCdvBd-->10¹⁵ FLOPs → 10²⁵ FLOPs</div>\n    </div>\n  </div>\n</section>\n\n<div data-page-node-id=\"CooUjkXPrPrkhwktme7Lfq\" class=\"wrap\">\n\n  <!--pnid:cHFCgSuJhjNeyZ4B14aNCN--><!-- ===== 第一章 ===== -->\n  <section data-page-node-id=\"Q8NUGFb9hJUW1ToAU6glXv\" class=\"chapter\">\n    <div data-page-node-id=\"tHS1094ApFnlJuuDJzmC0j\" class=\"chapter-head reveal-blur\">\n      <span data-page-node-id=\"8qBveJfN1Eqry8t1KhT7Tv\" class=\"no\"><!--pnid:axp3bnMoBcLtHsbNX6ve9C-->01</span>\n      <h2 data-page-node-id=\"8j71mdxRvO5X1Yl73oTWKd\"><span data-page-node-id=\"yYEJrG0LR5JTTKOs8yAQhM\" class=\"bar\"></span><!--pnid:kuv0GNd39XX529ZA4PWyQ1-->机械与电子曙光</h2>\n      <div data-page-node-id=\"e7VATOncV4ReQ4wj7Iutsg\" class=\"range\"><!--pnid:TSb4WtDGlwAw9qRXtXIhBp-->1642 — 1946</div>\n    </div>\n    <div data-page-node-id=\"f1XjeP3mO7CwahETolkmxb\" class=\"timeline\">\n      <div data-page-node-id=\"3JntDKFt1DzXCiV0MBtVLl\" class=\"tl-line\"></div>\n      <div data-page-node-id=\"utwNglKYBM1Lnoa0YIr69A\" class=\"tl-fill\" id=\"fill1\"></div>\n\n      <div data-page-node-id=\"ilJH0dWXIMU8ySzSFztq04\" class=\"milestone\">\n        <span data-page-node-id=\"6ZkYKGyztwaFYCcJqzDRXh\" class=\"tl-node\"></span>\n        <div data-page-node-id=\"zb3q2Ztto9KOIQ0n2RVVbM\" class=\"ms-card\">\n          <div data-page-node-id=\"ri9rg81xgMBsHoYwkhI4Ag\" class=\"ms-year\"><!--pnid:XJYuM96a6AtPZOqpPKzC6m-->1642</div>\n          <span data-page-node-id=\"MugGKQ02GYUD5nBSXuswsF\" class=\"ms-tag\"><!--pnid:JYPzkQZAEBDbzzYq3sKRDu-->机械计算</span>\n          <div data-page-node-id=\"k1Xn6qmZRFh3Cr8jNM8gyU\" class=\"ms-title\"><!--pnid:tj1BnMBD2dyoufhbFKE1pq-->帕斯卡加法器</div>\n          <p data-page-node-id=\"eUlfeiHyqjKTafGzqZvsyr\" class=\"ms-desc\"><!--pnid:G2lear0fcbLonfVy9Od8Qw-->法国数学家布莱兹·帕斯卡为帮助父亲算账，造出能自动进位的齿轮式加法器 Pascaline。人类第一次用机器替代手工计算。</p>\n        </div>\n      </div>\n\n      <div data-page-node-id=\"6Wmq1seO2opVRsfYte5EeI\" class=\"milestone\">\n        <span data-page-node-id=\"S0CDUMFEqktUwNao2NPiZV\" class=\"tl-node\"></span>\n        <div data-page-node-id=\"6QXGtDYWNyMoRCyL5KxZ94\" class=\"ms-card\">\n          <div data-page-node-id=\"yrywxTevBrwQ2SmrOE4MNY\" class=\"ms-year\"><!--pnid:QNmbpUb6vbKA53NO6OjDGD-->1837</div>\n          <span data-page-node-id=\"PVIiBXNvdDiEGt3XwC7P4P\" class=\"ms-tag\"><!--pnid:bOKXrSmEHEyDeqrXZYpCDY-->可编程构想</span>\n          <div data-page-node-id=\"IyixS0mu8E1ZO9yY0BeaWV\" class=\"ms-title\"><!--pnid:1YGr8OTO0Vell7wvOdqzWm-->巴贝奇分析机</div>\n          <p data-page-node-id=\"N2rAy0NEvdsXAvuyOeJOxQ\" class=\"ms-desc\"><!--pnid:L6FNH6KFcay3Ia6spKhw5x-->查尔斯·巴贝奇构想出可编程的通用计算装置，包含运算器、存储器与打孔卡输入。阿达·洛芙莱斯为其撰写算法，被后世尊为第一位程序员。</p>\n        </div>\n      </div>\n\n      <div data-page-node-id=\"CTkgeQjonUwMFGbqS7ACGb\" class=\"milestone\">\n        <span data-page-node-id=\"86Asjg1WZAHxaYjENW6wzT\" class=\"tl-node\"></span>\n        <div data-page-node-id=\"wBTSQmkkC5AiuzsIFK0SUR\" class=\"ms-card\">\n          <div data-page-node-id=\"Xj9Qw5DhW1OZA1FbiHWAzz\" class=\"ms-year\"><!--pnid:Din9xAWraONLX87exq0T2v-->1936</div>\n          <span data-page-node-id=\"iyrT27QWYF3xc3zOlfReTN\" class=\"ms-tag\"><!--pnid:jdwd39qdqRHLj4beUsvtPn-->理论奠基</span>\n          <div data-page-node-id=\"oSxXcGmBZee1imtOf0kfaK\" class=\"ms-title\"><!--pnid:jUkpUK5tzRFLYhmPfURKop-->图灵机</div>\n          <p data-page-node-id=\"VJCvfeqgMzg3qN5iyHX6ak\" class=\"ms-desc\"><!--pnid:0CQyejJ3na4N6hMEAvdOoV-->阿兰·图灵提出\"图灵机\"抽象模型，用一条无限纸带与一套规则定义了什么能被计算，为整个计算机科学奠定基石。</p>\n        </div>\n      </div>\n\n      <div data-page-node-id=\"xb8BzSDMyKbnIcI58QdpF9\" class=\"milestone\">\n        <span data-page-node-id=\"uVqHfeXbagc14RHYnog5Nd\" class=\"tl-node\"></span>\n        <div data-page-node-id=\"QiuMZLnfA2OAq50jNcKwKo\" class=\"ms-card\">\n          <div data-page-node-id=\"iDluDuoDs6TW6NTBK1avkr\" class=\"ms-year\"><!--pnid:SLWVd56dQ4ui122zESSye5-->1945</div>\n          <span data-page-node-id=\"Uk1DQZ3kiyTufBolzWaj3g\" class=\"ms-tag\"><!--pnid:SRQfgj4yrvrtMjx5CzvTv2-->架构范式</span>\n          <div data-page-node-id=\"kb02XVAQ8nobVzRdqdGhfL\" class=\"ms-title\"><!--pnid:v4dvfDvbRrftXaQ8RgsYKb-->冯·诺依曼架构</div>\n          <p data-page-node-id=\"2tWuXNOdFF06e0H7qbzTIG\" class=\"ms-desc\"><!--pnid:ZXEVyJq2sMXTi5yF6vCFWp-->约翰·冯·诺依曼提出\"存储程序\"思想：程序与数据同存于存储器、由运算器统一执行。这一架构沿用至今。</p>\n        </div>\n      </div>\n\n      <div data-page-node-id=\"CCl3e26xfOEywaWUr3pBaq\" class=\"milestone\">\n        <span data-page-node-id=\"ayouT2mFdyUgVnpPKEUJUL\" class=\"tl-node\"></span>\n        <div data-page-node-id=\"ArO8QNye1zjBw0lR2eDMtH\" class=\"ms-card\">\n          <div data-page-node-id=\"BXZvt9yMCcvQR9Es60GCb4\" class=\"ms-year\"><!--pnid:xIHB6gSmjHFqCDKRudTucW-->1946</div>\n          <span data-page-node-id=\"DGlptZ53s8R9br5ieFLuS8\" class=\"ms-tag\"><!--pnid:TArzDmNIEhlljxdtmiYUId-->电子计算机</span>\n          <div data-page-node-id=\"qw9zMxWOj0Ab3q6iRJY8mb\" class=\"ms-title\"><!--pnid:EFiR7kkw717HkJI8bw3Jso-->ENIAC 诞生</div>\n          <p data-page-node-id=\"c7Gzy8pM2Z0TiYBK9k1XG1\" class=\"ms-desc\"><!--pnid:yrjOLCzAN7nbqMzFb00cs9-->世界第一台通用电子数字计算机问世，重 30 吨，含约 18000 只电子管，每秒可完成约 5000 次加法。</p>\n          <div data-page-node-id=\"lntZdRdm2IN5dHoXZTMyqu\" class=\"ms-fact\"><b data-page-node-id=\"PRxpy3PHUXeBtdv8dCE9P6\"><!--pnid:WBRERLgSSwEfdynRdKOrFS-->18000</b><!--pnid:QDOMsSXinxDk0FhO1lsa6Q--> 只电子管 · <b data-page-node-id=\"nDZgQKnsgsyNrotBqRnR9I\"><!--pnid:rTs3LXnJL4A5GoEShxC3A7-->5000</b><!--pnid:QWkcDry6L7HKCs5GTUxC86--> 次加法/秒</div>\n        </div>\n      </div>\n\n    </div>\n  </section>\n\n  <!--pnid:4NAyd2rDmc0PRks9LvV67J--><!-- ===== 第二章 ===== -->\n  <section data-page-node-id=\"ngSxyp3t6CGi2VgrGnZ7wL\" class=\"chapter\">\n    <div data-page-node-id=\"58YigSNwO16c4Hkx32ubP6\" class=\"chapter-head reveal-blur\">\n      <span data-page-node-id=\"7dbwZ6wmqEKXs0pMq8xcKF\" class=\"no\"><!--pnid:UM749HwUz4AWSOURgxtNgu-->02</span>\n      <h2 data-page-node-id=\"LJHfn0AKaaFJGrDhq8fv1Z\"><span data-page-node-id=\"JFpfZ2kCQcQSnvDnN8OIVv\" class=\"bar\"></span><!--pnid:KJnADW9fosHfxnOG9jd0eQ-->晶体管与集成电路</h2>\n      <div data-page-node-id=\"RRBRpe8NelJJw1EAgoTYOO\" class=\"range\"><!--pnid:oH7tCKUWuvzBV2x1iqEy2h-->1947 — 1971</div>\n    </div>\n    <div data-page-node-id=\"FoooxMj1pa5Ixd7lcRVe4r\" class=\"timeline\">\n      <div data-page-node-id=\"2rjbzikhAbdBoPtczcbfcs\" class=\"tl-line\"></div>\n      <div data-page-node-id=\"oXxnxPhFzczP4vHhFncbfk\" class=\"tl-fill\" id=\"fill2\"></div>\n\n      <div data-page-node-id=\"trqcNKapaJeKh25uzZ4WsK\" class=\"milestone\">\n        <span data-page-node-id=\"CAeMs4wpog2tXcxjgFC4SD\" class=\"tl-node\"></span>\n        <div data-page-node-id=\"AqcgerLYepfbOsqi1BeXho\" class=\"ms-card\">\n          <div data-page-node-id=\"sLnKNqdIWFNEHmj8lpInAx\" class=\"ms-year\"><!--pnid:m4rjTnPYVWgMNzwwtIoQso-->1947</div>\n          <span data-page-node-id=\"SyjrLxWdfadJgY9yv8ADWa\" class=\"ms-tag\"><!--pnid:6tUEccqrXbRqfagOYDIwYR-->固体元件</span>\n          <div data-page-node-id=\"KQ98ObZlSx7BGjWoh0m8PX\" class=\"ms-title\"><!--pnid:xLxkxjrQGMGltCwCNsxaBO-->晶体管问世</div>\n          <p data-page-node-id=\"Yt7muWB7p58SW9fSzpvA8R\" class=\"ms-desc\"><!--pnid:OsbQCql5LWNZMZzEkhIUiH-->贝尔实验室的肖克利、巴丁、布拉顿发明点接触晶体管，用固体元件取代脆弱的真空管。三人因此获得 1956 年诺贝尔物理学奖。</p>\n        </div>\n      </div>\n\n      <div data-page-node-id=\"gPTcol4fK3uSmv6hKtzARp\" class=\"milestone\">\n        <span data-page-node-id=\"8Q48cbu5SP5h3fu72yi6Kb\" class=\"tl-node\"></span>\n        <div data-page-node-id=\"X3bLy6qVNfs00HYnvUyi9t\" class=\"ms-card\">\n          <div data-page-node-id=\"2FCZXuFGgnI1JPeFwdMPWS\" class=\"ms-year\"><!--pnid:4zm6Xcbu6c5tJtaYbOOWt8-->1958</div>\n          <span data-page-node-id=\"lKUBsdhT1udYGJ11t3Z5Uu\" class=\"ms-tag\"><!--pnid:nkaafRzB3SGk4qYRAtQCMb-->芯片开端</span>\n          <div data-page-node-id=\"ywIqx59DOnqEMaCbbVzyKV\" class=\"ms-title\"><!--pnid:iMvyHUQY6E6QAiEyramM68-->集成电路</div>\n          <p data-page-node-id=\"SqpZuGrOc9htargWLxLhb4\" class=\"ms-desc\"><!--pnid:2kb37UlNbR2nAy3tXM1bCv-->德州仪器的杰克·基尔比将多个晶体管集成在一块锗片上，造出第一块集成电路；次年罗伯特·诺伊斯用平面工艺实现可量产版本。</p>\n        </div>\n      </div>\n\n      <div data-page-node-id=\"MJx6nYtsN559kZxiKBNoNU\" class=\"milestone\">\n        <span data-page-node-id=\"thNgrrAAMRHr1S9zM6ieVg\" class=\"tl-node\"></span>\n        <div data-page-node-id=\"fLyhgq9TeH5K1c7jP5cjZO\" class=\"ms-card\">\n          <div data-page-node-id=\"EO6jhKUfOG6CgcZrQTAYrs\" class=\"ms-year\"><!--pnid:6Qke8ePMpMhA3nalBN2jU5-->1965</div>\n          <span data-page-node-id=\"5zbirLdaHfbMHCnFQWTtS8\" class=\"ms-tag\"><!--pnid:RINz7LIFDEKwW2aUBPuhDy-->增长引擎</span>\n          <div data-page-node-id=\"dyTGeGxwd1o3EaRN4jx9fz\" class=\"ms-title\"><!--pnid:Mv3Lk8IPS7LO0aNwNtvh5U-->摩尔定律</div>\n          <p data-page-node-id=\"ETYsOIsWU8kVYUxo8MHpMc\" class=\"ms-desc\"><!--pnid:Nym9wSKVAoIc7lMF1yQ5yt-->戈登·摩尔预言：集成电路上可容纳的晶体管数量，大约每两年翻一番。这一定律驱动了此后半个多世纪的算力指数级增长。</p>\n        </div>\n      </div>\n\n      <div data-page-node-id=\"iGWKvZdtmO70w75NLaCBk3\" class=\"milestone\">\n        <span data-page-node-id=\"YWMCkSXyuZpvq07Ch0RsyO\" class=\"tl-node\"></span>\n        <div data-page-node-id=\"XQe2e66V8ljmHWQ9bZBJ20\" class=\"ms-card\">\n          <div data-page-node-id=\"wxcEAx0OPV6z0NCCmXx9Kb\" class=\"ms-year\"><!--pnid:WcZDreFEWm3509F3R5sUti-->1971</div>\n          <span data-page-node-id=\"tDH3nVQXTczkQLYuQy6dpZ\" class=\"ms-tag\"><!--pnid:fgXMZebsuZKuhUkRbTjl4U-->微处理器</span>\n          <div data-page-node-id=\"CO9mmfhOpNB3GJ2gio27u1\" class=\"ms-title\"><!--pnid:avj5WZWBysOwFWan4D7IXF-->Intel 4004</div>\n          <p data-page-node-id=\"Poj7ageeH9F4ewGaVN5T9f\" class=\"ms-desc\"><!--pnid:ocdWD7fDmbp268Qo6eaaYe-->Intel 推出世界第一颗商用微处理器 4004，采用 10 微米工艺。一颗芯片上诞生了\"大脑\"，个人计算时代的大幕拉开。</p>\n          <div data-page-node-id=\"jiRBMM8kUXkkiwm9Q8JZXV\" class=\"ms-fact\"><b data-page-node-id=\"Io1JvPx8dUSYvxA8vKca9c\"><!--pnid:cTjJC0WdfaR7GhqV7F2psy-->2300</b><!--pnid:6IF8vnmlWGsSucwz6eafP7--> 个晶体管 · <b data-page-node-id=\"FCPdS2oPR4GJ4lGYZWkwQ1\"><!--pnid:CnFTFP8qJXeePpa6AjaMG2-->10</b><!--pnid:Nw4HH680AszVNhCB5RPFwS--> 微米工艺</div>\n        </div>\n      </div>\n\n    </div>\n  </section>\n\n  <!--pnid:USNagyCUvKbW01AyydeLvU--><!-- ===== 第三章 ===== -->\n  <section data-page-node-id=\"KfaPAnIqpmB1a15fTEOM3R\" class=\"chapter\">\n    <div data-page-node-id=\"fCix292EkLKplaPbiRzxs6\" class=\"chapter-head reveal-blur\">\n      <span data-page-node-id=\"IUfeX3rPLsY99a9sqqcYEY\" class=\"no\"><!--pnid:VfaFm9V1gDp1LQQSct4UN2-->03</span>\n      <h2 data-page-node-id=\"snR0wSF13L8jeIOwYClYwd\"><span data-page-node-id=\"jpZkTSyHnJba446kMpDtTG\" class=\"bar\"></span><!--pnid:p3lrMKPfkBEuY5UVx39eTQ-->个人计算机与互联网</h2>\n      <div data-page-node-id=\"NG5zef7bjRSguvkHMYYCgC\" class=\"range\"><!--pnid:6yHLloASIA4By5eMxA1v8T-->1971 — 2010</div>\n    </div>\n    <div data-page-node-id=\"eysbhAQR1Ru3hQSYmCf6f8\" class=\"timeline\">\n      <div data-page-node-id=\"cOq4kQs6zfsp5VkURlpgFc\" class=\"tl-line\"></div>\n      <div data-page-node-id=\"M9DIFj5sJ5GmXLTCGvV15c\" class=\"tl-fill\" id=\"fill3\"></div>\n\n      <div data-page-node-id=\"UeQ3j3udwXz9CNJJTg9jkI\" class=\"milestone\">\n        <span data-page-node-id=\"AjTfv5hz0Ifs2DwkcPKnz8\" class=\"tl-node\"></span>\n        <div data-page-node-id=\"y86xGAJnPtxsToCNY6tc4g\" class=\"ms-card\">\n          <div data-page-node-id=\"ol81maa6hje1F5vRIsruxH\" class=\"ms-year\"><!--pnid:JZ4d7kZbxC2j7nn2S9jIs4-->1976</div>\n          <span data-page-node-id=\"FyxxXLmMWnsQW5ZjtFKFOw\" class=\"ms-tag\"><!--pnid:hDkeRF3l7cgENIKbYr3Rdf-->个人电脑</span>\n          <div data-page-node-id=\"1nsW3axyUWdXtBjwtLzdzH\" class=\"ms-title\"><!--pnid:o3utqnz8XqEgGL6s2lZnHJ-->个人电脑起步</div>\n          <p data-page-node-id=\"35qoUL3X9KqOUjFdsvgewP\" class=\"ms-desc\"><!--pnid:UxGnqypja67maMXEnd5yrC-->Altair 8800 点燃个人计算的火种；Apple II 让计算机走进家庭与课堂。乔布斯与沃兹尼亚克在车库创办苹果公司。</p>\n        </div>\n      </div>\n\n      <div data-page-node-id=\"rxdgLH61B1nV4iGAHqTLP8\" class=\"milestone\">\n        <span data-page-node-id=\"pYYWnlotReE2W8JWloslWi\" class=\"tl-node\"></span>\n        <div data-page-node-id=\"LpU0Mp2GOhZ63bG4l9oh0O\" class=\"ms-card\">\n          <div data-page-node-id=\"p6JnSZ9LbXRuW0rNfLu8m4\" class=\"ms-year\"><!--pnid:9yTxHv0ZSL2swPOB58DgZF-->1981</div>\n          <span data-page-node-id=\"33go68UEow3jyZhEujlMCr\" class=\"ms-tag\"><!--pnid:0VBLNry0HCJt6iZ8H5YflJ-->开放标准</span>\n          <div data-page-node-id=\"wzxgnLIsefE3fZP6aVkZaV\" class=\"ms-title\"><!--pnid:plypeSAmGTc5jf7heViqzZ-->IBM PC 标准</div>\n          <p data-page-node-id=\"HF9XDRHPpVQQ5tkJURZ7IA\" class=\"ms-desc\"><!--pnid:SZy4Fncfzmx1HKSrQaYcBD-->IBM 发布 PC 5150，采用 Intel 8088 与微软 MS-DOS，确立个人电脑开放标准，兼容机产业随之崛起。</p>\n        </div>\n      </div>\n\n      <div data-page-node-id=\"fTdZ1h9uBprYKZboAdT7MJ\" class=\"milestone\">\n        <span data-page-node-id=\"O8Q9j5hSN5PlsFWwY6ngZT\" class=\"tl-node\"></span>\n        <div data-page-node-id=\"uq9nJFe3gZ326mPMs0KwS7\" class=\"ms-card\">\n          <div data-page-node-id=\"aRGQvetggAPFAG5zwtt1cD\" class=\"ms-year\"><!--pnid:dbvK8AmimCnAK2i8rsuYut-->1989</div>\n          <span data-page-node-id=\"VPb1MueXFQKCXkls695Y4J\" class=\"ms-tag\"><!--pnid:QGtE5E23oV5AYXvlFdZqWK-->信息网络</span>\n          <div data-page-node-id=\"mAajQ7sgryb0cPR7uf5oFr\" class=\"ms-title\"><!--pnid:qTfbJkByuRPEXNTOMnmTYB-->万维网</div>\n          <p data-page-node-id=\"L6EnbjbCzdIiVfMBvsbLAH\" class=\"ms-desc\"><!--pnid:3uw67S8C6wjh2pf68HeWyw-->蒂姆·伯纳斯-李在欧洲核子研究中心（CERN）发明万维网，用超链接把世界连接成一个信息网络。</p>\n        </div>\n      </div>\n\n      <div data-page-node-id=\"uTzRzg3mTNMSqHRnEgUDfp\" class=\"milestone\">\n        <span data-page-node-id=\"nSPD4Ay4cn22z1PLJMVUD4\" class=\"tl-node\"></span>\n        <div data-page-node-id=\"IFUYqiU0drIQFboJR2E1Bi\" class=\"ms-card\">\n          <div data-page-node-id=\"6PZSEdhNbomOW9fhYm66Vn\" class=\"ms-year\"><!--pnid:6pkVEFeC4ZfoWDDjkbJyQ9-->2006</div>\n          <span data-page-node-id=\"QuWANWUcj9ARCAZaPKsMJb\" class=\"ms-tag\"><!--pnid:LAqS4ESKSN4SDCHzJtli7i-->算力普惠</span>\n          <div data-page-node-id=\"rRnLq45aePLi6r8QFNggCb\" class=\"ms-title\"><!--pnid:L86vOBGWOdFFdqRv9bT8Tp-->云计算与 CUDA</div>\n          <p data-page-node-id=\"BK98kOrh4DTHe9X5aJu3fQ\" class=\"ms-desc\"><!--pnid:BX1JASIApZY1JPOqKdMFEN-->亚马逊推出 AWS，把算力变成随取随用的公共服务；同年 NVIDIA 发布 CUDA，为 GPU 通用计算铺路——为十年后的深度学习埋下伏笔。</p>\n        </div>\n      </div>\n\n      <div data-page-node-id=\"UfRagva4tuFeJ1ZO3oWuTx\" class=\"milestone\">\n        <span data-page-node-id=\"kAJlPtoR32YYRo2lMT6tDF\" class=\"tl-node\"></span>\n        <div data-page-node-id=\"TQvHFnwlMouwfLjRy2V9O1\" class=\"ms-card\">\n          <div data-page-node-id=\"CUZ6T0qCFnP9xUSliFvsIo\" class=\"ms-year\"><!--pnid:gQZSlfpmxr4kR0WLvcLHZW-->2007</div>\n          <span data-page-node-id=\"76nhhelMG2KOGpwazV0NGe\" class=\"ms-tag\"><!--pnid:4fp3yOfi0iVzgg1deuZ9lu-->移动计算</span>\n          <div data-page-node-id=\"mpZRunYjuTWMsyoDxqDZPX\" class=\"ms-title\"><!--pnid:VDxV1FL4WF5sQLw0BJomVL-->iPhone 问世</div>\n          <p data-page-node-id=\"CvZdveOtgQRpHd17YBcTlB\" class=\"ms-desc\"><!--pnid:ap17RsCxUl8CzlsSBspwsO-->苹果发布初代 iPhone，智能手机与移动互联网时代开启，算力开始随身而行。</p>\n        </div>\n      </div>\n\n    </div>\n  </section>\n\n  <!--pnid:HvLqqR2NGnY6R3UFIaCfQF--><!-- ===== 第四章 ===== -->\n  <section data-page-node-id=\"aXaC1DwjfsuDKlEEXretDG\" class=\"chapter\">\n    <div data-page-node-id=\"K5GocgG7EdcsGItQJrORDM\" class=\"chapter-head reveal-blur\">\n      <span data-page-node-id=\"GVbOpPRKi9EcCcUTWKanWN\" class=\"no\"><!--pnid:qDggFJKCivGq55ND44DTj4-->04</span>\n      <h2 data-page-node-id=\"ZgZdD3WoR2RoCZTI7ut9D8\"><span data-page-node-id=\"I1wvEyYtyNkQas29F8hIWC\" class=\"bar\"></span><!--pnid:zCM5IOIH5gAZ5HAtgsfdPy-->GPU 与深度学习觉醒</h2>\n      <div data-page-node-id=\"ZN2U5wad4ElR9A813MqTuc\" class=\"range\"><!--pnid:3QM7Bhdp5PbCO4BiLJm26D-->2006 — 2017</div>\n    </div>\n    <div data-page-node-id=\"RhSvEALUhZUsA8PiUyqDjh\" class=\"timeline\">\n      <div data-page-node-id=\"Sl6OEcIzDIoZEV1lvgmx5C\" class=\"tl-line\"></div>\n      <div data-page-node-id=\"Ap2LIe3ik3AlA9VVwQFYca\" class=\"tl-fill\" id=\"fill4\"></div>\n\n      <div data-page-node-id=\"VsYhVoqEkgQDC2EY27oPms\" class=\"milestone\">\n        <span data-page-node-id=\"Endn6uvdGSVHDyoNMT84vd\" class=\"tl-node\"></span>\n        <div data-page-node-id=\"1nh6e4bneT6Yz0R8YuKiYM\" class=\"ms-card\">\n          <div data-page-node-id=\"vF9jpaUElTKxz1XM4RMpKu\" class=\"ms-year\"><!--pnid:sOAbjYnOmAokb89SMYfNpg-->2012</div>\n          <span data-page-node-id=\"z3uQEED0kMRRBZ5evU12yP\" class=\"ms-tag\"><!--pnid:RX4slgo7D36FjFpYHMWFou-->深度学习</span>\n          <div data-page-node-id=\"Gi6O4Ol2u2wNwc07hnDzRi\" class=\"ms-title\"><!--pnid:LVykDzL9L9nsyIx61BQnnz-->AlexNet 革命</div>\n          <p data-page-node-id=\"QYa54NgIVzTu1wT66SwOpb\" class=\"ms-desc\"><!--pnid:fkoMIoJxuPWPk50XqAsnPe-->AlexNet 在 ImageNet 图像识别大赛夺冠，准确率大幅领先。它用两块 GTX 580 显卡训练，证明 GPU 并行算力是深度学习的燃料。</p>\n        </div>\n      </div>\n\n      <div data-page-node-id=\"0cLzBfqSbI0LssRBxzBMJS\" class=\"milestone\">\n        <span data-page-node-id=\"egDZz4omabk1bk3hn8ollC\" class=\"tl-node\"></span>\n        <div data-page-node-id=\"BArUzUNrPwjWQVZOkgQWQg\" class=\"ms-card\">\n          <div data-page-node-id=\"MjCLdGE7VL3LcedvWCfMuS\" class=\"ms-year\"><!--pnid:zVuY5PQ9cYSWTzfTicGCkE-->2016</div>\n          <span data-page-node-id=\"rFKEMqBsDNzvVpOtXUFbJS\" class=\"ms-tag\"><!--pnid:JBUs75tpTs4cVb66PtBPhs-->AI 里程碑</span>\n          <div data-page-node-id=\"0tunfBTPpl8Zzc30sR8Z5e\" class=\"ms-title\"><!--pnid:bYQB6Kk34e4nJH0VlG6SvI-->AlphaGo 战胜李世石</div>\n          <p data-page-node-id=\"UG3rd3smsdpubOvT7jpPVD\" class=\"ms-desc\"><!--pnid:Txecub4i5DVDFGXmyVH5Go-->DeepMind 的 AlphaGo 以 4:1 击败围棋世界冠军李世石，用约 170 块 GPU 与 TPU 训练，展示\"算力 + 算法 + 数据\"的合力。</p>\n        </div>\n      </div>\n\n      <div data-page-node-id=\"kM6pZLnvzH9twu7YpBYoRo\" class=\"milestone\">\n        <span data-page-node-id=\"ZWsPTKMLFjSto9Hyn00uXu\" class=\"tl-node\"></span>\n        <div data-page-node-id=\"Si4gXritZ8inIlUeR0hHQs\" class=\"ms-card\">\n          <div data-page-node-id=\"puoBENdGt2CAWwvhCoFljA\" class=\"ms-year\"><!--pnid:bWZN1gpwYVPjmHZzuEAZUB-->2017</div>\n          <span data-page-node-id=\"JDwL6Twn9BAnG69k4OvMoI\" class=\"ms-tag\"><!--pnid:gbWGxsT1aV0n8B8gEJE6VS-->架构基石</span>\n          <div data-page-node-id=\"1hL0GM5BRwI3p12j34LiOY\" class=\"ms-title\"><!--pnid:BjQ0sHZJQgjN0X4GB8RzKU-->Transformer 诞生</div>\n          <p data-page-node-id=\"pSHAlNcPqf97AIexaT8sgM\" class=\"ms-desc\"><!--pnid:u6lTA5MnxPWDh634eUYH8n-->谷歌团队发表《Attention Is All You Need》，提出 Transformer 架构。注意力机制取代循环结构，成为此后所有大模型的底座。</p>\n        </div>\n      </div>\n\n    </div>\n  </section>\n\n  <!--pnid:oTo9BpmOBnlZN7bHhktG3O--><!-- ===== 第五章 ===== -->\n  <section data-page-node-id=\"GTRfc3NRYkv6lNgGJQedHu\" class=\"chapter\">\n    <div data-page-node-id=\"nHpYlzC1vgr4yOR4JyufS0\" class=\"chapter-head reveal-blur\">\n      <span data-page-node-id=\"nbIBzgzlFhhyNiGMAxs3tf\" class=\"no\"><!--pnid:azWtqEqXHftl8GHJ4bG6fc-->05</span>\n      <h2 data-page-node-id=\"SuXKkj219OBuXKP1dz6lUs\"><span data-page-node-id=\"7kJ66fxhbS3iJC5E74EuOB\" class=\"bar\"></span><!--pnid:SquHls25dOlixtAgZJO7L3-->大模型与算力爆炸</h2>\n      <div data-page-node-id=\"eDOkM46UKhQEFDQCEUjCYF\" class=\"range\"><!--pnid:NoulJJucbYWsq2lvbOpcmp-->2017 — 至今</div>\n    </div>\n    <div data-page-node-id=\"u6iwXsQJFlbtMhGXd2uoqH\" class=\"timeline\">\n      <div data-page-node-id=\"G2b6b8F289XfnGXzRVzD8v\" class=\"tl-line\"></div>\n      <div data-page-node-id=\"0V8BxreD8Yj4cgWN32aMkY\" class=\"tl-fill\" id=\"fill5\"></div>\n\n      <div data-page-node-id=\"xWMtvph69YrIsG3ipu1503\" class=\"milestone\">\n        <span data-page-node-id=\"7Ig474cdv5GlRUVFaAX7u8\" class=\"tl-node\"></span>\n        <div data-page-node-id=\"ktJVdvRCrQlDcLSnquZjw9\" class=\"ms-card\">\n          <div data-page-node-id=\"ywXyGo6zTnNeJbr2oFQmxV\" class=\"ms-year\"><!--pnid:BImGmnnAgHcw7ObrDYLGDU-->2018</div>\n          <span data-page-node-id=\"dW9ZeTT3FJvSCOshnShMJo\" class=\"ms-tag\"><!--pnid:AGIwfnUrYiry0g35NqAVxk-->预训练</span>\n          <div data-page-node-id=\"2zFVKus5nB6QVmP1zjAsV6\" class=\"ms-title\"><!--pnid:OR7nBoS1PJh8gc7XWTTJmW-->预训练时代</div>\n          <p data-page-node-id=\"O4kYEj9v7NccZsXUVFp2zR\" class=\"ms-desc\"><!--pnid:c5enPpjp6EEbCWdXjYj4cU-->BERT、GPT-1 相继问世，\"预训练 + 微调\"范式确立，模型开始从海量文本中自主学习语言。</p>\n        </div>\n      </div>\n\n      <div data-page-node-id=\"SOp8QI2sbqQKHLTg1GhiXq\" class=\"milestone\">\n        <span data-page-node-id=\"RRPpyFu3FEbPN9CJhPPUhd\" class=\"tl-node\"></span>\n        <div data-page-node-id=\"OIwbPBzFTlz0v6B4tCCBdl\" class=\"ms-card\">\n          <div data-page-node-id=\"RincKSfDZ6PrloJ5i6HciV\" class=\"ms-year\"><!--pnid:z4eURgfOWCFCx6gMkMtLJg-->2020</div>\n          <span data-page-node-id=\"GBsKeaWJnvKLTwniPrp7ju\" class=\"ms-tag\"><!--pnid:0Zlv9fwGVKkIJivNIRbp3N-->规模效应</span>\n          <div data-page-node-id=\"6qihMPcom5Dx0LfZ035DFU\" class=\"ms-title\"><!--pnid:riFvOIHyjjCJfTiq0QOnJZ-->GPT-3 巨兽</div>\n          <p data-page-node-id=\"ZBxCAPEabHPh1NUumHhtP3\" class=\"ms-desc\"><!--pnid:qBfb4PuhgQxzvMCeK8Tykb-->OpenAI 发布 GPT-3，参数量达 1750 亿，训练算力约 3.14×10²³ FLOPs。规模效应的威力初显。</p>\n          <div data-page-node-id=\"HZvkuFsSKSEqWlmk9H2Jp8\" class=\"ms-fact\"><b data-page-node-id=\"QMME4rPl04WRYKQXCElBOf\"><!--pnid:7j3vRLuQB6Ybn1rI5Kxr7l-->1750 亿</b><!--pnid:zonwtHi3Pewt5kOo6YY42W--> 参数 · <b data-page-node-id=\"IvNsKU3CpFOsbzxJDGSFVi\"><!--pnid:Q7Irj1KFI5YMNPAAzKnoTa-->3.14×10²³</b><!--pnid:NxdpRS3wnLAQY5LmNQwpsl--> FLOPs</div>\n        </div>\n      </div>\n\n      <div data-page-node-id=\"JQdSMeIdkwClhVL5PPbbZE\" class=\"milestone\">\n        <span data-page-node-id=\"CVIb38QPyV4vdbKm7MhhiK\" class=\"tl-node\"></span>\n        <div data-page-node-id=\"NSBP637TBaE3CfgaBMcJxv\" class=\"ms-card\">\n          <div data-page-node-id=\"sSkE8LqO0nUw4SIOEXWQv4\" class=\"ms-year\"><!--pnid:iEzLwQD7LVOFiLZk9XWFRG-->2022</div>\n          <span data-page-node-id=\"pS1srlJdsdugrEEvpBPqrk\" class=\"ms-tag\"><!--pnid:W5By7VgkUgoXTObuo3wUff-->现象级产品</span>\n          <div data-page-node-id=\"FM9ELiNK2uYOHneTNcxj0h\" class=\"ms-title\"><!--pnid:o1NSsalrzBUn7b5MbVjbmo-->ChatGPT 引爆世界</div>\n          <p data-page-node-id=\"1Yy8M4X9CJQ2BxJf2qZruD\" class=\"ms-desc\"><!--pnid:Sc8InhwOf72Rd7LaxNkpKE-->ChatGPT 于 2022 年 11 月发布，两个月内月活突破 1 亿，成为史上增长最快的消费级应用。生成式 AI 走进大众视野。</p>\n        </div>\n      </div>\n\n      <div data-page-node-id=\"R4ly4QRAfxGLuh9JNskFpo\" class=\"milestone\">\n        <span data-page-node-id=\"vy2v0J8h6wDnvzTnHoQiG5\" class=\"tl-node\"></span>\n        <div data-page-node-id=\"NbOkP567oACzFKor2ixdT0\" class=\"ms-card\">\n          <div data-page-node-id=\"jA3sWfJPMualWUIJ4Kmq9o\" class=\"ms-year\"><!--pnid:i2S8QmbN1wRSOmbDun7knP-->2023–25</div>\n          <span data-page-node-id=\"mw9wltPH7r62B22PbTP8N7\" class=\"ms-tag\"><!--pnid:Cyh7uczt6HGF3cdGYdFl0F-->群雄并起</span>\n          <div data-page-node-id=\"LXp2wfh0Zbnwm7UaQY7N3K\" class=\"ms-title\"><!--pnid:L9Wti4YgpbQ6ritlihGdGu-->大模型爆发</div>\n          <p data-page-node-id=\"kcxEm6QQucw2RjWYEpSN6q\" class=\"ms-desc\"><!--pnid:YDjwturKYIMq3LqrqGK9rs-->GPT-4、Claude、Gemini 与开源模型 DeepSeek、Llama 等群雄并起，多模态、智能体、推理模型持续进化，模型能力与算力需求同步狂飙。</p>\n        </div>\n      </div>\n\n      <div data-page-node-id=\"oENGOxQXo8CioPnoZLoYb8\" class=\"milestone\">\n        <span data-page-node-id=\"cMabHdE2TOE5awqeg0Tzc1\" class=\"tl-node\"></span>\n        <div data-page-node-id=\"Ery95Hc3NH2s3L5WJQ5Awa\" class=\"ms-card\">\n          <div data-page-node-id=\"d2CVEvYgqFmjoNlIaILZyq\" class=\"ms-year\"><!--pnid:yrgY2FjLoeKtLY5jxWrqvY-->此刻</div>\n          <span data-page-node-id=\"O9gQ0tMsy75CxHUtOBTXaA\" class=\"ms-tag\"><!--pnid:Gl7UXD1EXE8nkVEzynkQso-->智算时代</span>\n          <div data-page-node-id=\"KNPpvCcvF7BgObw1fptePQ\" class=\"ms-title\"><!--pnid:k7X5YHAXuvpJm4wqOcuUcD-->万卡集群时代</div>\n          <p data-page-node-id=\"swBxpnQBnhMY42fCt6DMlf\" class=\"ms-desc\"><!--pnid:h09CLihdUNv8RKjLP5rEA5-->万卡集群成为标配，H100、B200 等专用加速芯片供不应求，数据中心走向液冷与绿电。算力，已成为新时代的基础能源。</p>\n        </div>\n      </div>\n\n    </div>\n  </section>\n\n  <!--pnid:amKqrraTStZZiLCIPq7uDT--><!-- ===== 算力曲线 ===== -->\n  <section data-page-node-id=\"tXiT8sN5n6Mi8eeYciQ26x\" class=\"growth\">\n    <h3 data-page-node-id=\"vnit1C0f3i5QAfvNhdCKEZ\" class=\"reveal-blur\"><!--pnid:sGOjbAzRORsv8ykmGNuOTU-->算力的指数跃迁</h3>\n    <p data-page-node-id=\"3CswkbPzU4T2wGgbJVZfrp\" class=\"lead reveal\"><!--pnid:E27YrwYDlqS0wsjkry0CMP-->训练算力（FLOPs）以对数尺度攀升：从 AlexNet 时代到前沿大模型，十年间跨越了约 10 个数量级。</p>\n    <div data-page-node-id=\"QqaU6uzpWHB0hvdjo3bTPK\" class=\"chart-card reveal\">\n      <svg data-page-node-id=\"8f5wYKkUDrkGMvDZsxw96T\" aria-label=\"训练算力增长曲线（对数尺度）\" role=\"img\" viewBox=\"0 0 680 300\">\n        <defs data-page-node-id=\"ZsW44I542cYXdzwyHrDv4Y\">\n          <linearGradient data-page-node-id=\"sdui3eyAWNfya4e8bOmotb\" id=\"gline\" x1=\"0\" x2=\"1\" y1=\"0\" y2=\"0\">\n            <stop data-page-node-id=\"MIioPmXTlJSVcSiIco98Z7\" offset=\"0\" stop-color=\"#22d3ee\"/>\n            <stop data-page-node-id=\"q0qA8JFGNkeu9wSjmvuBez\" offset=\"0.5\" stop-color=\"#3b82f6\"/>\n            <stop data-page-node-id=\"I9MVaxTj3f604Fvzq0IJkN\" offset=\"1\" stop-color=\"#8b5cf6\"/>\n          </linearGradient>\n          <linearGradient data-page-node-id=\"5TYo9E22MqYVFGVPUijuku\" id=\"garea\" x1=\"0\" x2=\"0\" y1=\"0\" y2=\"1\">\n            <stop data-page-node-id=\"VDOnPYIouK2DH4XKGIO6Jm\" offset=\"0\" stop-color=\"#22d3ee\" stop-opacity=\"0.25\"/>\n            <stop data-page-node-id=\"nIt48lM7qW2SMxZeCdYG0B\" offset=\"1\" stop-color=\"#22d3ee\" stop-opacity=\"0\"/>\n          </linearGradient>\n        </defs>\n        <!--pnid:cOoLSRqV23mfajLJxE20JA--><!-- 网格 -->\n        <g data-page-node-id=\"wCmXQiwTa4B3tD9uDinfse\" class=\"chart-axis\">\n          <line data-page-node-id=\"xlUex6XEENBqUe3ilg1jYQ\" x1=\"40\" x2=\"40\" y1=\"30\" y2=\"250\"/>\n          <line data-page-node-id=\"niIAIZOYOn00rz6ibXaQLC\" x1=\"40\" x2=\"640\" y1=\"250\" y2=\"250\"/>\n          <line data-page-node-id=\"0GoOio2Ia9BFGwa9GL4J1v\" stroke-dasharray=\"3 5\" x1=\"40\" x2=\"640\" y1=\"150\" y2=\"150\"/>\n          <line data-page-node-id=\"1IlFJM3JUM0yDn2mctNvcZ\" stroke-dasharray=\"3 5\" x1=\"40\" x2=\"640\" y1=\"70\" y2=\"70\"/>\n        </g>\n        <!--pnid:0ACevjEtpyQBh60tOphuU6--><!-- 刻度标签 -->\n        <g data-page-node-id=\"J1hvtlSIqijdfKbUA0s7rS\" class=\"chart-label\">\n          <text data-page-node-id=\"opSOsXeGbpeWMpFEtoghxp\" text-anchor=\"end\" x=\"30\" y=\"255\"><!--pnid:dvkPQvX23h5dVXjostLCdB-->10¹²</text>\n          <text data-page-node-id=\"oq0SMnoWo9FnLlryql5kOi\" text-anchor=\"end\" x=\"30\" y=\"155\"><!--pnid:0UWp8UHk7aBXR0hMgACh1w-->10¹⁷</text>\n          <text data-page-node-id=\"GSKsNGygtnBb8P1SXLfUjW\" text-anchor=\"end\" x=\"30\" y=\"75\"><!--pnid:vfVn7qcJc2CyB73U2UJGH5-->10²²</text>\n          <text data-page-node-id=\"xq4Q9YUFQraHgReQVgvmad\" x=\"40\" y=\"272\"><!--pnid:sVZq1iC2Ct51ANDcivAoDl-->2012</text>\n          <text data-page-node-id=\"N7TMDfNAsP3f3cwFHHcVyp\" text-anchor=\"end\" x=\"640\" y=\"272\"><!--pnid:z8itjqazUhJkqCj3APQRIn-->2024</text>\n        </g>\n        <!--pnid:BwWlADbSKiyFjLRgQyaOnO--><!-- 面积 -->\n        <path data-page-node-id=\"cQVJoYD4C2FGgpFN6oKrtd\" class=\"chart-area\" d=\"M40,240 C140,236 200,210 260,190 C330,168 390,120 460,88 C530,56 590,40 640,30 L640,250 L40,250 Z\"/>\n        <!--pnid:w0UhPcNIqM38ZkRTc21hCr--><!-- 曲线 -->\n        <path data-page-node-id=\"MxgPPXI75kBQdEk8YcpuAM\" class=\"chart-line\" d=\"M40,240 C140,236 200,210 260,190 C330,168 390,120 460,88 C530,56 590,40 640,30\"/>\n        <!--pnid:YjW38B0mHdApPjrwnYrc4c--><!-- 数据点 -->\n        <circle data-page-node-id=\"hHY5fbhz5WVT69FjbJoF5X\" class=\"chart-pt-ring\" cx=\"40\" cy=\"240\" r=\"9\"/>\n        <circle data-page-node-id=\"aZQtNwnKOTEFGdlUadUxYh\" class=\"chart-pt\" cx=\"40\" cy=\"240\" r=\"3.5\"/>\n        <circle data-page-node-id=\"iIt4hpfklJRCPpT70kQYO1\" class=\"chart-pt-ring\" cx=\"260\" cy=\"190\" r=\"9\"/>\n        <circle data-page-node-id=\"UI7gOPQxj87baBxERnJYJT\" class=\"chart-pt\" cx=\"260\" cy=\"190\" r=\"3.5\"/>\n        <circle data-page-node-id=\"8JfDOMfucpOqNWQgXNB8im\" class=\"chart-pt-ring\" cx=\"460\" cy=\"88\" r=\"9\"/>\n        <circle data-page-node-id=\"FKa84Io4iQKF5qOSZarOum\" class=\"chart-pt\" cx=\"460\" cy=\"88\" r=\"3.5\"/>\n        <circle data-page-node-id=\"Pejewfu7emIRe8KGemNEHX\" class=\"chart-pt-ring\" cx=\"640\" cy=\"30\" r=\"9\"/>\n        <circle data-page-node-id=\"Q1iUaO8SBjj0pWwAKxlot8\" class=\"chart-pt\" cx=\"640\" cy=\"30\" r=\"3.5\"/>\n        <!--pnid:B2P4gAkAMNIzAm6BlLX6hP--><!-- 标注 -->\n        <g data-page-node-id=\"S1M51BN0MTJhacaeCSPqBV\" class=\"chart-label\" fill=\"#ffffff\" font-size=\"11\">\n          <text data-page-node-id=\"E8vkab16NBodUOVe5Uw7Sx\" opacity=\"0.9\" text-anchor=\"middle\" x=\"40\" y=\"222\"><!--pnid:HSiINaScDtbexhqfzgw34q-->AlexNet</text>\n          <text data-page-node-id=\"IZBAySo0cFKyufoIs4Yxdt\" opacity=\"0.9\" text-anchor=\"middle\" x=\"260\" y=\"172\"><!--pnid:gMNLxX382RkDBnZcti67Zq-->AlphaGo Zero</text>\n          <text data-page-node-id=\"5rVDw82YlEil2jbHcjAxaw\" opacity=\"0.9\" text-anchor=\"middle\" x=\"460\" y=\"70\"><!--pnid:D15bE0yyTR9KNlLipMUHdh-->GPT-3</text>\n          <text data-page-node-id=\"7f5W3Lonls5wNJonse7dcV\" fill=\"#22d3ee\" text-anchor=\"middle\" x=\"640\" y=\"22\"><!--pnid:J9IEiJZdFI7CGdjLwuhYnh-->前沿大模型</text>\n        </g>\n      </svg>\n    </div>\n  </section>\n\n  <!--pnid:qLcSn5JKkK320XvqPiIbQE--><!-- ===== 结语 ===== -->\n  <section data-page-node-id=\"Bjc2vGrkZOtXYEl6996kEQ\" class=\"outro\">\n    <div data-page-node-id=\"PYkDfCcu2GBREBvEVBOh0X\" class=\"quote reveal-blur\">\n      <p data-page-node-id=\"35oJuIxfdjkG0xGPIY0DY8\"><!--pnid:xPRauc7uNP5DxWzXmNejQa-->从帕斯卡的一台加法器，到图灵的一张纸；从一颗晶体管，到一座智算中心。算力的每一次跃迁，都在重写<span data-page-node-id=\"WRavcqbvaYautLDvQeak2Z\" class=\"g\"><!--pnid:S4Doy8bJhWBJsumnaU7E5q-->\"机器能做什么\"</span><!--pnid:kf5PoLqBUYsc91pAQATQwy-->的边界。</p>\n      <p data-page-node-id=\"6wtLRVPy7s79WbJ7wziLjs\" style=\"margin-top:20px; font-size:0.72em; color:var(--text-secondary); font-weight:500\"><!--pnid:bCh8KrjJBZTl23Frew99kK-->下一章，正在此刻被写就。</p>\n    </div>\n  </section>\n\n</div>\n\n<footer data-page-node-id=\"PsA14fUUKX3EBSsPx2ITHG\">\n  <div data-page-node-id=\"jluPkvUccULvIjR9edbcnZ\" class=\"wrap\" style=\"display:flex; justify-content:space-between; gap:16px; flex-wrap:wrap; width:100%\">\n    <span data-page-node-id=\"8cogYrVSzI6JjMAlYDX2DN\" class=\"sig\"><!--pnid:7FBPqVcOH3kmZpNBJj5irW-->计算进化史 · 从晶体管到大模型时代</span>\n    <span data-page-node-id=\"KFydibbFbUCIFIcgYgDd8T\"><!--pnid:iv9nQ6YlaZ8OQmiYPuDvD5-->计算的故事</span>\n  </div>\n</footer>\n\n<!--pnid:eCjedBtgYdhRP0Z5D8ESir--><!-- ===== 底部二进制彩带 ===== -->\n<section data-page-node-id=\"iXDD0hxouyGsGJsTLFutuZ\" class=\"binary\">\n  <div data-page-node-id=\"CJMub0tgEOtU62bonvvcJ8\" class=\"wrap\">\n    <div data-page-node-id=\"CkcOVQ9527FxxHA74ku86F\" class=\"binary-head reveal\">\n      <span data-page-node-id=\"AHbbkMY3pVbImH0QMUwzd4\" class=\"prompt\"><!--pnid:7A6FCRystni6dh4cjkP53l-->$</span>\n      <span data-page-node-id=\"jLrKkEOY6wRnUAUzcSZTZF\" class=\"msg\"><!--pnid:xakHYaKmX89Hr8McL8qKBO-->echo \"祝大家健健康康！\" | xxd -b</span>\n      <span data-page-node-id=\"tooBbtDOIJZ7Q5pPRRGwjK\" class=\"hint\"><!--pnid:sT9vWlrKh6KAcODlmuwToa-->UTF-8 · 每个汉字 3 字节</span>\n    </div>\n    <div data-page-node-id=\"PioiIUOqEwPjW2lzMxQwm4\" class=\"b-stage reveal\" id=\"binaryStage\"></div>\n  </div>\n</section>\n\n";

(function () {
  var reduce = window.matchMedia('(prefers-reduced-motion: reduce)').matches;

  /* 顶部进度条 */
  var bar = document.getElementById('progressBar');
  function onScroll() {
    var h = document.documentElement;
    var max = h.scrollHeight - h.clientHeight;
    var p = max > 0 ? (h.scrollTop || document.body.scrollTop) / max : 0;
    if (bar) bar.style.width = (p * 100).toFixed(2) + '%';
    /* 各章节主轴填充 */
    document.querySelectorAll('.tl-fill').forEach(function (f) {
      var tl = f.parentElement;
      var r = tl.getBoundingClientRect();
      var vh = window.innerHeight;
      var prog = Math.min(1, Math.max(0, (vh - r.top) / (vh + tl.offsetHeight)));
      f.style.height = (prog * 100) + '%';
    });
  }
  window.addEventListener('scroll', onScroll, { passive: true });
  onScroll();

  /* 滚动入场 */
  var els = document.querySelectorAll('.reveal, .reveal-blur');
  if ('IntersectionObserver' in window && !reduce) {
    var io = new IntersectionObserver(function (entries) {
      entries.forEach(function (e) {
        if (e.isIntersecting) { e.target.classList.add('in'); io.unobserve(e.target); }
      });
    }, { threshold: 0.12, rootMargin: '0px 0px -40px 0px' });
    els.forEach(function (el) { io.observe(el); });
  } else {
    els.forEach(function (el) { el.classList.add('in'); });
  }

  /* 时间轴节点点亮 */
  var nodes = document.querySelectorAll('.milestone');
  if ('IntersectionObserver' in window) {
    var io2 = new IntersectionObserver(function (entries) {
      entries.forEach(function (e) {
        if (e.isIntersecting) { e.target.classList.add('lit'); io2.unobserve(e.target); }
      });
    }, { threshold: 0.35 });
    nodes.forEach(function (el) { io2.observe(el); });
  } else {
    nodes.forEach(function (el) { el.classList.add('lit'); });
  }

  /* 数字滚动 */
  function count(el) {
    var target = parseFloat(el.getAttribute('data-count')) || 0;
    if (reduce) { el.textContent = target.toLocaleString(); return; }
    var start = null, dur = 1800;
    function step(ts) {
      if (!start) start = ts;
      var t = Math.min(1, (ts - start) / dur);
      var eased = 1 - Math.pow(1 - t, 4); /* easeOutQuart */
      var val = Math.round(target * eased);
      el.textContent = val.toLocaleString();
      if (t < 1) requestAnimationFrame(step);
    }
    requestAnimationFrame(step);
  }
  var counters = document.querySelectorAll('.num[data-count]');
  if ('IntersectionObserver' in window) {
    var io3 = new IntersectionObserver(function (entries) {
      entries.forEach(function (e) {
        if (e.isIntersecting) { count(e.target); io3.unobserve(e.target); }
      });
    }, { threshold: 0.6 });
    counters.forEach(function (el) { io3.observe(el); });
  } else {
    counters.forEach(function (el) { count(el); });
  }

  /* 底部二进制彩带 */
  var stage = document.getElementById('binaryStage');
  if (stage) {
    var msg = '祝大家健健康康！';
    var enc = new TextEncoder();
    Array.from(msg).forEach(function (ch) {
      var bytes = Array.from(enc.encode(ch));
      var unit = document.createElement('div');
      unit.className = 'b-unit';
      bytes.forEach(function (byte) {
        var bits = byte.toString(2).padStart(8, '0');
        var bw = document.createElement('span');
        bw.className = 'b-byte';
        for (var i = 0; i < 8; i++) {
          var b = document.createElement('span');
          b.className = 'b-bit ' + (bits.charAt(i) === '1' ? 'b1' : 'b0');
          b.textContent = bits.charAt(i);
          bw.appendChild(b);
        }
        unit.appendChild(bw);
      });
      var label = document.createElement('span');
      label.className = 'b-label';
      label.textContent = ch;
      unit.appendChild(label);
      stage.appendChild(unit);
    });
  }
})();

  return () => { faces.forEach(face => document.fonts.delete(face)); };
}
